#include <iostream>

struct Animal {
    virtual void speak() const { std::cout << "Hello\n"; }
    virtual ~Animal() = default;
};
struct Dog : Animal {
    void speak() const override { std::cout << "Woof\n"; }
};

int main() {
    Dog pet;
    const Animal& animal = pet;
    animal.speak();
}

#include <iostream>

struct Shape {
    virtual int sides() const = 0;
    virtual ~Shape() = default;
};
struct Square : Shape { int sides() const override { return 4; } };

int main() {
    Square tile;
    std::cout << tile.sides() << " sides\n";
}
